import { ThreeCore } from './ThreeCore';
import { Core } from './Core/Core';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import * as THREE from 'three';

export class Solution {
    threeCore: ThreeCore;
    core: Core;
    static Init(id: string) {
        const app = new Solution(id);
        app.Dummy();
    }
    constructor(id: string = 'main') {
        // console.log(id);
        this.threeCore = new ThreeCore(id);
        this.core = new Core(this.threeCore);
        this.bindEvent();
        this.BindRenderer();
        
        
        const files = ['onlyaCube-clean-static.fbx', 'solarPanel.fbx' ]

        for(let i = 0 ; i < files.length; ++i){
            const path = process.env.PUBLIC_URL + '/static/data/model/' + files[i]
            console.log(path, FBXLoader);
            
            const scaleFactor = 0.01;
            const loader = new FBXLoader();
            loader.load(path, (fbx) => {
                // console.log(fbx)
                fbx.castShadow = true;
                fbx.receiveShadow = true;
                // fbx.material.envMapIntensity = 1.0; // 환경 반사 강도

                fbx.traverse((child) => {
                    if (child.isMesh) {
                    child.castShadow = true;
                    child.receiveShadow = true;

                    
                    const oldMat = child.material
                    // console.log(oldMat)
                    // child.material = new THREE.MeshStandardMaterial({
                    //     map: oldMat.map ?? null,
                    //     metalness: 0.2,
                    //     roughness: 0.5,
                    //     color: oldMat.color ?? new THREE.Color(0xffffff),
                    //     normalMap: oldMat.normalMap ?? null,
                    // });


                    if (Array.isArray(child.material)) {
                    child.material = child.material.map((oldMat) =>
                        new THREE.MeshStandardMaterial({
                        map: oldMat.map ?? null,
                        color: oldMat.color ?? new THREE.Color(0xffffff),
                        normalMap: oldMat.normalMap ?? null,
                        metalness: 0.2,
                        roughness: 0.5,
                        })
                    )
                    } else {
                    const oldMat = child.material
                    child.material = new THREE.MeshStandardMaterial({
                        map: oldMat.map ?? null,
                        color: oldMat.color ?? new THREE.Color(0xffffff),
                        normalMap: oldMat.normalMap ?? null,
                        metalness: 0.2,
                        roughness: 0.5,
                    })
                    }






                    }

                    
                });

                fbx.scale.set(scaleFactor, scaleFactor, scaleFactor);
                this.threeCore.scene.add(fbx);

                },(xhr) => {
                    console.log((xhr.loaded / xhr.total) * 100 + '% loaded');
                },
                (error) => {
                    console.error('An error happened', error);
                }
            );
        }
    }
    Dummy() {
        //
    }
    bindEvent() {
        this.threeCore.MouseDown = (e: MouseEvent) => this.core.mouseDown(e);
        this.threeCore.MouseMove = (e: MouseEvent) => this.core.mouseMove(e);
        this.threeCore.MouseUp = (e: MouseEvent) => this.core.mouseUp(e);
    }
    BindRenderer() {
        this.threeCore.render = () => this.core.render();
    }
    destroy(){
        this.core.destroy();
        this.threeCore.destroy();
    }
}
